modules.mandate.rego:
package trusted
import rego.v1

# A sample trading mandate for Hyperliquid: reading is free, an order must be
# in a listed market and under the per-order limit, and all orders of one UTC
# day together stay under the daily limit. Everything else is refused.

day := input.evaluated_at_unix - (input.evaluated_at_unix % 86400)

spent := input.state.spent if input.state.day == day
spent := 0 if input.state.day != day

on_exchange if {
    input.operation == "http.request"
    input.parameters.host == data.exchange
}

orders := input.parameters.body.action.orders if {
    on_exchange
    input.parameters.path == "/exchange"
    input.parameters.method == "POST"
    input.parameters.body.action.type == "order"
    count(input.parameters.body.action.orders) > 0
}

# Amounts are kept in cents, rounded up, because state holds integers only.
cents(order) := ceil(to_number(order.s) * to_number(order.p) * 100)

within_limits if {
    every order in orders {
        order.a in data.assets
        cents(order) <= data.max_order_cents
    }
}

total := spent + sum([cents(order) | some order in orders])

decision := {"decision": "allow", "reason_codes": ["read_only"]} if {
    on_exchange
    input.parameters.path == "/info"
} else := {
    "decision": "allow",
    "reason_codes": ["within_mandate"],
    "next_state": {"day": day, "spent": total},
} if {
    within_limits
    total <= data.daily_limit_cents
} else := {"decision": "deny", "reason_codes": ["over_daily_limit"]} if {
    within_limits
} else := {"decision": "deny", "reason_codes": ["outside_mandate"]}
